
// ============================================================
// CryptoJS - تشفير وفك تشفير البيانات
// نسخة مبسطة وسريعة
// ============================================================

(function(global) {
    'use strict';

    // ============================================================
    // دالة تشفير بسيطة (XOR)
    // ============================================================
    function encrypt(text, key) {
        if (!text || !key) return text;
        try {
            const result = [];
            const keyChars = key.split('');
            for (let i = 0; i < text.length; i++) {
                const charCode = text.charCodeAt(i) ^ keyChars[i % keyChars.length].charCodeAt(0);
                result.push(String.fromCharCode(charCode));
            }
            return btoa(result.join(''));
        } catch (e) {
            return text;
        }
    }

    // ============================================================
    // دالة فك تشفير بسيطة (XOR)
    // ============================================================
    function decrypt(encrypted, key) {
        if (!encrypted || !key) return encrypted;
        try {
            const text = atob(encrypted);
            const result = [];
            const keyChars = key.split('');
            for (let i = 0; i < text.length; i++) {
                const charCode = text.charCodeAt(i) ^ keyChars[i % keyChars.length].charCodeAt(0);
                result.push(String.fromCharCode(charCode));
            }
            return result.join('');
        } catch (e) {
            return encrypted;
        }
    }

    // ============================================================
    // دالة توليد مفتاح عشوائي
    // ============================================================
    function generateKey(length = 32) {
        const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()_+-=';
        let result = '';
        for (let i = 0; i < length; i++) {
            result += chars.charAt(Math.floor(Math.random() * chars.length));
        }
        return result;
    }

    // ============================================================
    // دالة SHA256 مبسطة
    // ============================================================
    function sha256(message) {
        const msg = String(message);
        let hash = 0;
        for (let i = 0; i < msg.length; i++) {
            hash = ((hash << 5) - hash) + msg.charCodeAt(i);
            hash |= 0;
        }
        return Math.abs(hash).toString(16).padStart(8, '0');
    }

    // ============================================================
    // دالة تشفير كلمة المرور
    // ============================================================
    function hashPassword(password, salt) {
        const salted = password + (salt || 'tomodachi_salt_2024');
        return sha256(salted);
    }

    // ============================================================
    // تصدير الكائن
    // ============================================================
    global.CryptoJS = {
        AES: {
            encrypt: function(text, key) {
                return {
                    toString: function() {
                        return encrypt(JSON.stringify(text), key);
                    }
                };
            },
            decrypt: function(encrypted, key) {
                return {
                    toString: function(enc) {
                        try {
                            const decrypted = decrypt(encrypted, key);
                            return JSON.parse(decrypted);
                        } catch (e) {
                            return decrypt(encrypted, key);
                        }
                    }
                };
            }
        },
        enc: {
            Utf8: {
                parse: function(str) { return str; },
                stringify: function(str) { return str; }
            },
            Base64: {
                stringify: function(wordArray) {
                    return btoa(String.fromCharCode.apply(null, wordArray));
                }
            }
        },
        SHA256: {
            toString: function(message) {
                return sha256(message);
            }
        },
        lib: {
            WordArray: {
                random: function(bytes) {
                    const result = [];
                    for (let i = 0; i < bytes; i++) {
                        result.push(Math.floor(Math.random() * 256));
                    }
                    return result;
                }
            }
        },
        // دوال مساعدة إضافية
        hashPassword: hashPassword,
        generateKey: generateKey,
        encrypt: encrypt,
        decrypt: decrypt
    };

})(window);

console.log('🔐 CryptoJS loaded successfully');
